/bin/bash -lc "cd [workspace path] && python3 -c \"
from PIL import Image
import numpy as np
a = np.array(Image.open('first_frame.png')).astype(int)
H,W,_ = a.shape
r,g,b = a[...,0],a[...,1],a[...,2]
# classify each coarse block
gh, gw = 24, 32  # each cell 8x8
for gy in range(gh):
    line=''
    for gx in range(gw):
        blk = a[gy*8:(gy+1)*8, gx*8:(gx+1)*8]
        mr,mg,mb = blk[...,0].mean(),blk[...,1].mean(),blk[...,2].mean()
        if mb > mr+25 and mb > mg+10:
            ch='B'  # blue
        elif mr>170 and mg>170 and mb>170:
            ch='.'  # near white/light
        elif mr<70 and mg<70 and mb<70:
            ch='#'  # dark
        elif mr>mg+25 and mr>mb+15:
            ch='R'  # red/brown
        elif mg>mr+15 and mg>mb+10:
            ch='G'
        elif mr>120 and mg>100 and mb<110 and abs(mr-mg)<35:
            ch='y'  # yellow/tan
        else:
            ch='o'
        line+=ch
    print(line)
\""

